/* ============================================================
   PERSON — the join. One frozen record per ledger owner, keyed
   by lowercased username. Fields:
     name     display name (pool casing, else ledger casing)
     role     ledger group (pool role, else most-granted group)
     sprite   {col, row} portrait tile, or null
     blurb    researched reason sentence, else ROLE_BLURB[role]
     granted  % of granted pool (ledger)
     total    % of total (ledger)
     months   grant months, newest first (ledger)
   Every page reads from here; nobody re-joins the sources. ============================================================ */

/* most-frequent ledger group per person — same rule the old pool used */
function dominantRole(monthCategories) {
  const counts = new Map();
  for (const cats of monthCategories) {
    for (const c of cats) counts.set(c, (counts.get(c) || 0) + 1);
  }
  let best = null, bestN = -1;
  for (const [c, n] of counts) {
    if (n > bestN) { best = c; bestN = n; }
  }
  const RENAMED = {
    INFRASTRUCTURE: 'Infrastructure',
    'KNOWLEDGE/TOOLS': 'Knowledge Sharer',
    'KNOWLEDGE SHARERS': 'Knowledge Sharer',
    ARTISTS: 'Artist',
    CORE: 'Core',
  };
  return RENAMED[best] || null;
}

/* per-person grant months + categories, parsed once from the ledger mirror */
const historyByKey = (() => {
  const map = new Map();
  for (const g of GRANTS) {
    const segs = g.grants.split('|');
    for (const seg of segs) {
      const m = seg.match(/^([A-Z /]+):\s*(.*)$/);
      let cats = [], names = [];
      if (m) { cats = [m[1].trim()]; names = m[2].split(';').map((s) => s.trim()).filter(Boolean); }
      else { names = seg.split(';').map((s) => s.trim()).filter(Boolean); }
      for (const n of names) {
        const key = n.toLowerCase().trim();
        if (!map.has(key)) map.set(key, []);
        map.get(key).push({ month: g.month, categories: cats });
      }
    }
  }
  return map;
})();

function buildPerson() {
  const byKey = new Map();

  // start from the ledger — every owner gets a record
  for (const o of OWNERSHIP) {
    const key = o.username.toLowerCase().trim();
    byKey.set(key, {
      name: o.username,
      role: null,
      sprite: null,
      blurb: null,
      granted: o.granted,
      total: o.total,
      months: [],
    });
  }

  // portrait rows: display casing, sprite, and role (pool role wins)
  for (const p of PORTRAITS) {
    const key = p[0].toLowerCase().trim();
    const rec = byKey.get(key);
    if (!rec) continue; // portrait for a non-ledger name — ignore, pool row was 120-matched so this shouldn't fire
    rec.name = p[0];
    rec.role = p[1];
    rec.sprite = { col: p[2], row: p[3] };
  }

  // grant history: months + dominant role where the pool didn't supply one
  for (const [key, hist] of historyByKey) {
    const rec = byKey.get(key);
    if (!rec) continue;
    rec.months = hist.map((h) => h.month);
    if (!rec.role) rec.role = dominantRole(hist.map((h) => h.categories));
  }

  // reasons: the researched sentence, else the group blurb
  for (const [key, rec] of byKey) {
    const r = REASONS[key];
    rec.blurb = (r && r.sentence) ? r.sentence : ROLE_BLURB[rec.role] || null;
  }

  const frozen = {};
  for (const [key, rec] of byKey) {
    frozen[key] = Object.freeze(rec);
  }
  return Object.freeze(frozen);
}

/** Every contributor, lowercase-keyed. THE canonical record. */
export const PERSON = buildPerson();

/** The portrait-bearing subset, as PERSON records — the field deals from this. */
export const CONTRIBUTOR_POOL = Object.freeze(
  PORTRAITS
    .map((p) => PERSON[p[0].toLowerCase().trim()])
    .filter(Boolean)
    .map(Object.freeze)
);
